	('light', 'Papier', 'light', 'Encre noire sur papier clair.', false, NULL, true, false, 'Base', 'Base', true, '{"colors":["#f4f5fa","#3a8fba","#9a7020"],"tone":"light","tagline":"Une lecture plus claire et apaisée."}'),
	('violet', 'Galactique', 'theme-violet', 'Nuit violette, encre pâle, ruban bleu ciel.', false, NULL, true, false, 'Rare', 'Rares', true, '{"colors":["#03020b","#9b7cff","#73d8ff"],"tone":"dark","tagline":"Constellations, nébuleuses et lumière d’orbite."}'),
	('green', 'Sylvan', 'theme-green', 'Vert de sous-bois, encre de mousse, ruban d’or pâle.', false, NULL, true, false, 'Rare', 'Rares', true, '{"colors":["#031108","#51c56d","#d8c16a"],"tone":"dark","tagline":"Jungle dense, canopée vivante et sève lumineuse."}'),
	('aquaris', 'Aquaris', 'theme-aquaris', 'Bleu des grands fonds, encre d’écume, ruban d’or ancien.', false, NULL, true, false, 'Rare', 'Rares', true, '{"colors":["#011018","#48d6ef","#e5c878"],"tone":"dark","tagline":"Royaume englouti, cyan abyssal et or ancien."}'),
	('easter', 'Printemps éveillé', 'theme-easter', 'Vert tendre, encre de feuille, ruban rose.', true, '2026-05-01T00:00:00.000Z', true, false, 'Saisonnier', 'Saisonniers', true, '{"colors":["#f7fff2","#7fdc82","#ffd86b","#ffb6d8"],"tone":"light","tagline":"Printemps vivant, mignon et coloré."}'),
	('halloween', 'Nuit des âmes', 'theme-halloween', 'Prune nocturne, encre chaude, ruban lilas.', true, '2026-11-02T00:00:00.000Z', true, false, 'Saisonnier', 'Saisonniers', true, '{"colors":["#0a0911","#ff8f2b","#7c59ff","#d8d2ff"],"tone":"dark","tagline":"Presque creepy, entre citrouille et brume."}'),
	('noel', 'Veillée hivernale', 'theme-noel', 'Vert sapin, encre de neige, ruban doré.', true, '2027-01-06T00:00:00.000Z', true, false, 'Saisonnier', 'Saisonniers', true, '{"colors":["#08140d","#d84a52","#2ea85f","#f2c66d"],"tone":"dark","tagline":"Festif, chaleureux, rouge, vert et or."}'),
	('bloodmoon', 'Lune de sang', 'theme-bloodmoon', 'Noir rougi, encre rosée, ruban carmin.', false, NULL, true, false, 'Fondateur', 'Fondateur', true, '{"colors":["#050102","#e3133f","#f0c76f"],"tone":"dark","tagline":"Lune rouge souveraine et tension rituelle."}')
