INSERT INTO "oaths" ("id", "name", "weapon", "pv_growth", "ep_growth", "em_growth", "base_damage", "damage_type", "rank", "hidden", "evolves_from", "icon", "category", "is_builtin", "lore", "branches") VALUES
	('duelliste', 'Duelliste', 'Épée moyenne du serment', 6, 6, 2, 11, 'Tranchant', 'basic', false, NULL, '⚔', 'melee', true, 'Le Duelliste n''est pas appelé par la violence. Il est appelé par l''instant juste. Ce serment choisit les êtres capables de garder une ligne claire quand le combat devient confus, ceux qui savent que la victoire se joue parfois dans un demi-pas, une respiration retenue, un angle refusé. Son épée moyenne du serment ne cherche pas à impressionner : elle répond. Elle se place dans la main comme une décision ancienne, sobre, précise, presque familière. Le Duelliste est le combattant de la mesure et de l''exigence. Pas le plus brutal, pas le plus spectaculaire, mais celui qui transforme chaque mouvement en phrase nette. Face à lui, l''adversaire ne combat pas seulement une lame : il combat une lecture.', '{"bA":{"nom":"Branche A — L''Élan Tranchant","style":"Brutalité","descPhys":"De loin, le sol crisse sous une impulsion brusque. Le corps s''élance, bas, rapide, et la lame arrive avec lui — avant même que l''adversaire ait compris ce qui s''est passé. De près : aucun élan. La lame s''enfonce plein centre, et dans le même geste, le porteur pousse — bras, épaule, poids du corps. L''adversaire part en arrière, les pieds quittent le sol une fraction de seconde.","flavor":"Cette branche donne au Duelliste son autorité la plus simple : décider de la distance. De loin, il transforme l''espace en accélération. De près, il transforme l''impact en recul forcé. L''adversaire ne choisit plus vraiment où se tient le combat ; il découvre seulement où le Duelliste l''a déplacé.","paliers":[{"niv":2,"nom":"Élan Tranchant","cout":"6 EM — 1 action","desc":"À distance : dash vers la cible + frappe 6+Niv. Au corps à corps : frappe 10+Niv + repousse l''adversaire à distance (les deux doivent utiliser une action de déplacement pour se rapprocher)."},{"niv":5,"nom":"Élan Tranchant","cout":"6 EM — 1 action","desc":"À distance : 10+Niv. Au corps à corps : 14+Niv + repousse."},{"niv":7,"nom":"Élan Tranchant","cout":"6 EM — 1 action","desc":"À distance : 14+Niv. Au corps à corps : 18+Niv + repousse."},{"niv":10,"nom":"Élan Tranchant","cout":"6 EM — 1 action","desc":"À distance : 18+Niv. Au corps à corps : 22+Niv + repousse."}]},"bB":{"nom":"Branche B — Taille Double","style":"Fluidité","descPhys":"La lame trace une première ligne, puis revient sans pause dans l''autre sens. Deux mouvements qui n''en font qu''un — fluides, enchaînés, comme écrits d''avance.","flavor":"Taille Double n''est pas une pluie de coups. C''est une phrase en deux syllabes. La première oblige la défense à se révéler, la seconde punit l''espace qu''elle vient d''ouvrir. Le Duelliste ne frappe pas plus vite pour faire joli : il coupe le temps de réaction adverse en deux.","paliers":[{"niv":2,"nom":"Taille Double","cout":"5 EM — 1 action","desc":"2 frappes consécutives traitées individuellement. L''adversaire doit dépenser une défense séparée pour chacune. 5+Niv par frappe (total : 10+Niv×2)."},{"niv":5,"nom":"Taille Double","cout":"5 EM — 1 action","desc":"8+Niv par frappe (total : 16+Niv×2)."},{"niv":7,"nom":"Taille Double","cout":"5 EM — 1 action","desc":"11+Niv par frappe (total : 22+Niv×2)."},{"niv":10,"nom":"Taille Double","cout":"5 EM — 1 action","desc":"14+Niv par frappe (total : 28+Niv×2)."}]}}'),
	('bretteur', 'Bretteur', 'Épée fine du serment', 5, 7, 3, 12, 'Tranchant', 'seasoned', true, 'duelliste', '⚔', 'melee', true, 'Le Bretteur est ce que devient le Duelliste quand la maîtrise cesse d''être droite et devient insaisissable. Il ne cherche plus seulement l''ouverture : il la fabrique. Sa lame fine du serment vit dans les appuis, les feintes, les micro-reculs, les gestes qui ressemblent à des erreurs jusqu''à ce qu''il soit trop tard. Le Bretteur impose un rythme nerveux, presque insolent. Il provoque une défense, la déplace d''un souffle, puis frappe exactement là où l''adversaire vient de se trahir. On ne le tient jamais tout à fait. On croit l''avoir lu, et c''est souvent à cet instant précis qu''il a déjà changé de phrase.', '{"bA":{"nom":"Branche A — Feinte de Fer","style":"Précision","descPhys":"La lame part trop tôt, trop visible — presque volontairement. L''adversaire réagit, et c''est là que le vrai coup arrive, décalé d''un souffle, porté dans l''angle que la défense vient d''abandonner.","flavor":"Le Bretteur vend une erreur comme d''autres vendent une menace. Il donne à l''adversaire quelque chose à défendre, puis retire le sens du geste au dernier moment. La cible ne tombe pas dans un piège grossier ; elle tombe dans sa propre bonne réaction.","paliers":[{"niv":10,"nom":"Feinte de Fer","cout":"6 EM — 1 action","desc":"Frappe 8+Niv. Si la cible utilise une défense, elle dépense 2 EP supplémentaires. Si elle ne défend pas, la frappe gagne +4 dégâts."},{"niv":13,"nom":"Feinte de Fer","cout":"6 EM — 1 action","desc":"Frappe 12+Niv. Défense adverse : +3 EP dépensés. Sans défense : +6 dégâts."},{"niv":16,"nom":"Feinte de Fer","cout":"6 EM — 1 action","desc":"Frappe 16+Niv. Défense adverse : +4 EP dépensés. Sans défense : +8 dégâts."},{"niv":20,"nom":"Feinte de Fer","cout":"6 EM — 1 action","desc":"Frappe 20+Niv. Défense adverse : +5 EP dépensés. Sans défense : +10 dégâts."}]},"bB":{"nom":"Branche B — Pas Rompu","style":"Fluidité","descPhys":"Le Bretteur pivote au dernier instant. Le corps se décale, la lame accompagne le mouvement, et l''attaque adverse glisse dans le vide pendant qu''une ligne nette apparaît en retour.","flavor":"Pas Rompu n''est pas une fuite. C''est une disparition minuscule. Le Bretteur laisse l''attaque passer à l''endroit où il était, puis revient dans l''angle mort avec la cruauté tranquille de quelqu''un qui avait prévu le coup avant son départ.","paliers":[{"niv":10,"nom":"Pas Rompu","cout":"5 EM — réaction","desc":"Lorsqu''une attaque ciblée est esquivée, le Bretteur peut riposter : 5+Niv dégâts. Utilisable 1 fois par tour."},{"niv":13,"nom":"Pas Rompu","cout":"5 EM — réaction","desc":"Riposte après esquive : 8+Niv dégâts. Le Bretteur peut aussi se replacer à distance courte."},{"niv":16,"nom":"Pas Rompu","cout":"5 EM — réaction","desc":"Riposte après esquive : 11+Niv dégâts. La prochaine attaque du Bretteur contre cette cible coûte -1 EP."},{"niv":20,"nom":"Pas Rompu","cout":"5 EM — réaction","desc":"Riposte après esquive : 14+Niv dégâts. Si la cible a raté son attaque, elle perd 1 action de déplacement ce tour."}]}}'),
	('claymore', 'Claymore', 'Claymore du serment', 7, 4, 2, 16, 'Tranchant lourd', 'seasoned', true, 'duelliste', '⚔', 'melee', true, 'Le Claymore naît quand un Duelliste renonce à la finesse comme unique réponse et choisit le poids. Ce serment ne récompense pas la vitesse : il récompense l''engagement total. Sa grande lame du serment impose une question simple à chaque adversaire : es-tu vraiment prêt à recevoir ça ? Le porteur avance peu, mais chaque pas change la géographie du combat. Il lève la lame comme on lève une menace, accepte d''être lisible, et transforme cette lisibilité en terreur. Le Claymore ne surprend pas par l''angle. Il prévient, puis frappe quand même. Sa force est là : l''adversaire voit venir le coup et doute malgré tout de pouvoir l''arrêter.', '{"bA":{"nom":"Branche A — Posture Haute","style":"Pression lourde","descPhys":"Le porteur remonte l''espadon au-dessus de l''épaule. La garde paraît ouverte, presque provocante, mais la lame suspendue annonce un coup si lourd que l''adversaire doit décider avant même qu''il parte.","flavor":"Posture Haute fait de la préparation une arme. Le Claymore annonce le danger, garde la lame suspendue, et force l''adversaire à vivre une seconde entière sous la promesse de l''impact. Ce n''est pas discret. C''est pire : c''est inévitable.","paliers":[{"niv":10,"nom":"Posture Haute","cout":"6 EM — 1 action","desc":"Entre en posture jusqu''au prochain tour. La prochaine Frappe Haute coûte 10 EP, inflige 20+Niv dégâts et retire 12 EP si la cible bloque."},{"niv":13,"nom":"Posture Haute","cout":"6 EM — 1 action","desc":"Frappe Haute : 24+Niv dégâts, 10 EP. Si la cible bloque, elle perd 14 EP."},{"niv":16,"nom":"Posture Haute","cout":"6 EM — 1 action","desc":"Frappe Haute : 28+Niv dégâts, 10 EP. Si la cible bloque, elle perd 16 EP et ne peut pas se déplacer au prochain round."},{"niv":20,"nom":"Posture Haute","cout":"6 EM — 1 action","desc":"Frappe Haute : 32+Niv dégâts, 10 EP. Si la cible bloque, elle perd 20 EP. Sur défense réussie, la cible subit tout de même 25% des dégâts sous forme d''impact."}]},"bB":{"nom":"Branche B — Fendre la Ligne","style":"Brise-ligne","descPhys":"L''espadon part en arc large, lent, plein. Ce n''est pas une coupe élégante : c''est une masse de métal qui traverse la garde, les appuis et la certitude de tenir bon.","flavor":"Fendre la Ligne n''est pas fait pour courir après les fuyards. C''est une réponse aux gardes, aux fronts, aux certitudes. Le Claymore frappe là où l''ennemi pensait tenir, jusqu''à ce que la position cesse d''être une protection et devienne un piège.","paliers":[{"niv":10,"nom":"Fendre la Ligne","cout":"7 EM — 1 action","desc":"Frappe 10+Niv dégâts. Brise-ligne : si la cible bloque, le coup traverse le blocage et ajoute en dégâts le bonus que le blocage aurait retiré. Si la cible a déjà défendu ce tour, elle dépense +3 EP pour défendre cette attaque."},{"niv":13,"nom":"Fendre la Ligne","cout":"7 EM — 1 action","desc":"Frappe 14+Niv dégâts. Brise-ligne : si la cible bloque, le coup traverse le blocage et ajoute en dégâts le bonus que le blocage aurait retiré. Contre une cible en garde, parade ou protection, ajoute +4 dégâts."},{"niv":16,"nom":"Fendre la Ligne","cout":"7 EM — 1 action","desc":"Frappe 18+Niv dégâts. Brise-ligne : si la cible bloque, le coup traverse le blocage et ajoute en dégâts le bonus que le blocage aurait retiré. Une défense réussie ne permet pas à la cible de se replacer gratuitement."},{"niv":20,"nom":"Fendre la Ligne","cout":"7 EM — 1 action","desc":"Frappe 22+Niv dégâts. Brise-ligne : si la cible bloque, le coup traverse le blocage et ajoute en dégâts le bonus que le blocage aurait retiré. Si la cible défend, sa prochaine défense coûte +2 EP jusqu''à la fin du tour suivant."}]}}'),
	('lame-d-honneur', 'Lame d''Honneur', 'Épée claire du serment', 7, 5, 3, 10, 'Tranchant', 'seasoned', true, 'duelliste', '⚔', 'melee', true, 'La Lame d''Honneur ne protège pas le monde entier. Elle choisit une cible et transforme ce choix en serment. Là où d''autres combattants dispersent leur attention, elle resserre le champ de bataille jusqu''à ce qu''il ne reste qu''un duel, une faute à punir, une promesse à tenir. Sa lame claire ne brille pas pour faire joli : elle désigne. Une fois le duel juré, la Lame d''Honneur devient terrifiante contre l''adversaire choisi et presque volontairement médiocre contre le reste. Ce n''est pas une faiblesse accidentelle, c''est le prix de sa foi. Elle gagne en puissance parce qu''elle accepte de n''avoir qu''une obsession.', '{"bA":{"nom":"Branche A — Duel Juré","style":"Duel","descPhys":"La Lame d''Honneur pointe une cible. Le monde ne disparaît pas, mais tout semble se resserrer entre deux corps, deux souffles, deux volontés. Chaque pas hors de ce duel paraît plus lourd, presque moins légitime.","flavor":"Duel Juré ferme la porte. L''EM investi devient une mise à prix spirituelle : il ne revient pas simplement avec le temps, parce qu''il appartient désormais à la promesse. La Lame d''Honneur gagne le droit de frapper sa cible comme une sentence, mais tout ce qui n''est pas cette cible devient secondaire, presque indigne de sa lame.","paliers":[{"niv":10,"nom":"Duel Juré","cout":"5 EM — 1 action — EM non régénérable","desc":"Désigne une cible jusqu''à sa mort, la fin du combat ou rupture validée staff. Contre elle : +40% dégâts. Contre toute autre cible : -60% dégâts. Si la cible meurt, récupère jusqu''à 6 EP dépensés pendant ce duel."},{"niv":13,"nom":"Duel Juré","cout":"5 EM — 1 action — EM non régénérable","desc":"Contre la cible jurée : +55% dégâts. Contre les autres : -70% dégâts. Si la cible meurt, récupère jusqu''à 9 EP dépensés pendant ce duel."},{"niv":16,"nom":"Duel Juré","cout":"5 EM — 1 action — EM non régénérable","desc":"Contre la cible jurée : +70% dégâts. Contre les autres : -80% dégâts. Si la cible meurt, récupère jusqu''à 12 EP dépensés pendant ce duel."},{"niv":20,"nom":"Duel Juré","cout":"5 EM — 1 action — EM non régénérable","desc":"Contre la cible jurée : +90% dégâts. Contre les autres : -90% dégâts. Si la cible meurt, récupère toute l''EP dépensée pendant ce duel, dans la limite de son maximum d''EP."}]},"bB":{"nom":"Branche B — Sentence du Duel","style":"Exécution","descPhys":"La lame claire ne cherche plus les ouvertures générales. Elle revient toujours vers la même présence, le même angle, la même faute. Chaque coup ressemble moins à une attaque qu''à une ligne de plus dans une condamnation.","flavor":"Sentence du Duel est la partie la plus froide du serment. Pas de panache inutile, pas de grande protection héroïque : seulement la même cible, encore, jusqu''à rupture. Chaque frappe rappelle que la Lame d''Honneur a choisi son ennemi et que ce choix doit aller au bout.","paliers":[{"niv":10,"nom":"Sentence du Duel","cout":"4 EM — 1 action — cible jurée uniquement","desc":"Frappe 10+Niv dégâts. Si la cible est sous Duel Juré, ajoute +4 dégâts et marque 1 EP dépensé comme récupérable si elle meurt."},{"niv":13,"nom":"Sentence du Duel","cout":"4 EM — 1 action — cible jurée uniquement","desc":"Frappe 14+Niv dégâts. Si la cible est sous Duel Juré, ajoute +7 dégâts et marque 2 EP dépensés comme récupérables si elle meurt."},{"niv":16,"nom":"Sentence du Duel","cout":"4 EM — 1 action — cible jurée uniquement","desc":"Frappe 18+Niv dégâts. Si la cible est sous Duel Juré, ajoute +10 dégâts. Si elle défend, sa défense coûte +2 EP."},{"niv":20,"nom":"Sentence du Duel","cout":"4 EM — 1 action — cible jurée uniquement","desc":"Frappe 22+Niv dégâts. Si la cible est sous Duel Juré, ajoute +14 dégâts. Si cette attaque tue la cible, la récupération d''EP du Duel Juré se déclenche immédiatement."}]}}'),
	('sauvageon', 'Sauvageon', 'Hache à deux mains du serment', 5, 8, 1, 14, 'Tranchant', 'basic', false, NULL, '🪓', 'melee', true, 'Le Sauvageon est le serment de ceux qui ont appris à vivre avant d''apprendre à se tenir droits. Il ne leur offre pas la brutalité : il la reconnaît déjà là, enfouie dans les épaules, dans la mâchoire, dans cette façon d''avancer quand tout conseille de reculer. Sa hache à deux mains du serment est une évidence primitive, lourde, presque insultante dans sa simplicité. Elle ne promet ni élégance ni pardon. Elle promet que quelque chose va céder. Le Sauvageon n''est pas seulement fort : il est habité par une survie ancienne, une rage utile, une endurance qui donne l''impression que le monde l''a cogné longtemps sans réussir à le coucher.', '{"bA":{"nom":"Branche A — Spirale Brisante","style":"AOE","descPhys":"La hache s''abat sur le sol avec tout le poids du porteur. Le sol se fissure sous l''impact. Une onde de choc se propage en cercle — quiconque se tient à portée sent le sol lui échapper sous les pieds.","flavor":"Spirale Brisante est une décision sans nuance. Le Sauvageon ne demande pas au champ de bataille de se ranger proprement : il frappe le point qui doit exploser et accepte que tout ce qui traîne trop près paie le prix. C''est violent, dangereux, parfois sale, mais jamais hésitant.","paliers":[{"niv":2,"nom":"Spirale Brisante","cout":"5 EM — 1 action","desc":"Frappe le sol. Toutes entités au corps à corps — ennemies ET alliées — subissent 8+Niv dégâts contondants."},{"niv":5,"nom":"Spirale Brisante","cout":"5 EM — 1 action","desc":"12+Niv à toutes entités au CAC."},{"niv":7,"nom":"Spirale Brisante","cout":"5 EM — 1 action","desc":"16+Niv à toutes entités au CAC."},{"niv":10,"nom":"Spirale Brisante","cout":"5 EM — 1 action","desc":"20+Niv à toutes entités au CAC."}]},"bB":{"nom":"Branche B — Lancer Bestial","style":"Précision","descPhys":"Aucune préparation. Aucun calcul apparent. Le Sauvageon saisit sa hache, pivote, et la lâche avec une force brute qui n''a rien d''élégant — et pourtant elle file droit, implacable, comme si la violence elle-même avait décidé de l''endroit où elle devait atterrir.","flavor":"Lancer Bestial transforme la hache en verdict. Le Sauvageon abandonne volontairement son arme pour envoyer toute sa force en ligne droite. Le risque fait partie de la beauté du geste : pendant un instant, il n''a plus rien en main, mais l''adversaire, lui, doit vivre avec ce qui vient de le percuter.","paliers":[{"niv":2,"nom":"Lancer Bestial","cout":"8 EM — 1 action","desc":"Lance la hache sur une cible à distance : 18+Niv. Après le lancer, le porteur n''a plus son arme — réinvoquer (1 EM, 1 action) ou aller la récupérer (2 actions)."},{"niv":5,"nom":"Lancer Bestial","cout":"8 EM — 1 action","desc":"24+Niv."},{"niv":7,"nom":"Lancer Bestial","cout":"8 EM — 1 action","desc":"30+Niv."},{"niv":10,"nom":"Lancer Bestial","cout":"8 EM — 1 action","desc":"38+Niv."}]}}'),
	('croise', 'Croisé', 'Bouclier du serment', 8, 3, 2, 6, 'Contondant', 'basic', false, NULL, '🛡', 'melee', true, 'Le Croisé est un refus. Refus de reculer, refus de céder la place, refus de laisser le chaos décider seul de ce qui tombe. Ce serment ne cherche pas les âmes douces ; il cherche celles qui portent déjà un devoir trop lourd et qui continuent malgré tout. Son bouclier du serment n''est pas un accessoire défensif. C''est une frontière mobile, un morceau de mur arraché au monde et confié à deux bras. Le Croisé avance avec une gravité presque cérémonielle. Quand il se place, il dit sans parler : ici, ça ne passe plus. Ses victoires ne sont pas toujours rapides, mais elles ont la solidité des choses qu''on n''a pas réussi à faire plier.', '{"bA":{"nom":"Branche A — Bash Cinglant","style":"Offensif","descPhys":"Le bouclier s''illumine d''une lueur jaunâtre, brève et sourde. Puis il part en travers — un choc brut, sans élégance. À chaque impact, quelque chose se renforce dans le Croisé — une résistance qui monte, comme si le combat lui-même nourrissait sa capacité à encaisser.","flavor":"Bash Cinglant rappelle que le bouclier n''est pas un objet passif. Chaque impact est une déclaration : le Croisé ne se contente pas d''encaisser, il répond avec le poids même de sa défense. Plus il frappe, plus son corps semble comprendre qu''il doit rester debout.","paliers":[{"niv":2,"nom":"Bash Cinglant","cout":"6 EM — 1 action (CAC uniquement)","desc":"Frappe avec le bouclier : 5+Niv dégâts. Chaque hit augmente les PV maximum du Croisé de +3 PV max. Ces PV bonus disparaissent à la fin du combat."},{"niv":5,"nom":"Bash Cinglant","cout":"6 EM — 1 action","desc":"7+Niv dégâts. +5 PV max par hit."},{"niv":7,"nom":"Bash Cinglant","cout":"6 EM — 1 action","desc":"10+Niv dégâts. +7 PV max par hit."},{"niv":10,"nom":"Bash Cinglant","cout":"6 EM — 1 action","desc":"13+Niv dégâts. +10 PV max par hit."}]},"bB":{"nom":"Branche B — Appel du Bouclier","style":"Aggro","descPhys":"Le bouclier s''illumine d''une lueur jaunâtre, intense, presque aveuglante. Le Croisé le frappe contre le sol avec fracas. Il se dresse, immobile, regard fixe — et quelque chose dans cette lumière et cette posture dit aux ennemis que c''est lui, et lui seul, qu''ils doivent abattre.","flavor":"Appel du Bouclier n''est pas un cri pour attirer l''attention. C''est une injonction. Le Croisé devient le problème central de la scène, la cible qu''on ne peut plus ignorer. Chaque ennemi qui mord à l''appel renforce le mur qu''il essaie d''abattre.","paliers":[{"niv":2,"nom":"Appel du Bouclier","cout":"6 EM — 1 action","desc":"Provoque toutes les entités ennemies à portée. +3+Niv PV max par monstre provoqué. Mobs intelligents : effet 1 tour. Mobs agressifs : permanent. Désactivable sans action."},{"niv":5,"nom":"Appel du Bouclier","cout":"6 EM — 1 action","desc":"+5+Niv PV max par monstre provoqué."},{"niv":7,"nom":"Appel du Bouclier","cout":"6 EM — 1 action","desc":"+7+Niv PV max par monstre provoqué."},{"niv":10,"nom":"Appel du Bouclier","cout":"6 EM — 1 action","desc":"+10+Niv PV max par monstre provoqué."}]}}'),
	('rodeur', 'Rôdeur', 'Dague du serment', 2, 5, 3, 8, 'Tranchant', 'basic', false, NULL, '🗡', 'melee', true, 'Le Rôdeur appartient aux bords du monde : couloirs mal éclairés, routes secondaires, ruines où l''on entend trop tard le pas qui approche. Ce serment choisit les êtres qui survivent par mouvement, par silence, par instinct. Sa dague du serment n''a rien d''une arme glorieuse. Elle est courte, nerveuse, personnelle, faite pour apparaître au moment exact où l''adversaire croyait encore contrôler la distance. Le Rôdeur ne domine pas le combat, il l''échappe. Il glisse hors des prises, revient dans les angles morts, transforme la fragilité en vitesse. Le danger chez lui n''est pas massif : il est soudain.', '{"bA":{"nom":"Branche A — Rafale de Lames","style":"Mêlée","descPhys":"La dague ne s''arrête pas. Premier coup, deuxième, troisième — enchaînés sans temps mort, sans respiration. La main du Rôdeur disparaît dans une succession de gestes trop rapides pour être lus séparément.","flavor":"Rafale de Lames ne cherche pas le coup parfait. Elle noie la défense sous des décisions trop rapprochées. Trois entailles, trois urgences, une seule respiration pour comprendre. Le Rôdeur gagne parce que la cible n''a pas le temps de répondre correctement à tout.","paliers":[{"niv":2,"nom":"Rafale de Lames","cout":"6 EM — 1 action","desc":"3 frappes consécutives sur une même cible. Chaque frappe traitée individuellement (défense séparée pour chacune). 1+Niv par frappe (total : 3+Niv×3)."},{"niv":5,"nom":"Rafale de Lames","cout":"6 EM — 1 action","desc":"3+Niv par frappe (total : 9+Niv×3)."},{"niv":7,"nom":"Rafale de Lames","cout":"6 EM — 1 action","desc":"5+Niv par frappe (total : 15+Niv×3)."},{"niv":10,"nom":"Rafale de Lames","cout":"6 EM — 1 action","desc":"7+Niv par frappe (total : 21+Niv×3)."}]},"bB":{"nom":"Branche B — Lancer Lié","style":"Distance","descPhys":"La dague quitte la main, frappe, et revient — comme si un fil invisible la ramenait. Le Rôdeur n''attend pas. La lame est déjà de retour avant même que l''adversaire ait compris qu''elle était partie.","flavor":"Lancer Lié donne au Rôdeur une menace impossible à confisquer. La dague part, mord, revient. L''adversaire ne peut pas compter sur la perte de l''arme pour respirer : elle est déjà revenue, comme une mauvaise nouvelle qui connaît le chemin.","paliers":[{"niv":2,"nom":"Lancer Lié","cout":"5 EM — 1 action","desc":"Lance la dague sur une cible à distance (hors CAC uniquement). 5+Niv. La dague revient automatiquement et gratuitement."},{"niv":5,"nom":"Lancer Lié","cout":"5 EM — 1 action","desc":"9+Niv. Retour automatique."},{"niv":7,"nom":"Lancer Lié","cout":"5 EM — 1 action","desc":"13+Niv. Retour automatique."},{"niv":10,"nom":"Lancer Lié","cout":"5 EM — 1 action","desc":"17+Niv. Retour automatique."}]}}'),
	('traqueur', 'Traqueur', 'Lance du serment', 2, 7, 2, 8, 'Tranchant', 'basic', false, NULL, '🏹', 'melee', true, 'Le Traqueur ne chasse pas pour courir. Il chasse pour réduire les options. Ce serment reconnaît les esprits qui savent attendre, lire les habitudes, rendre chaque fuite un peu plus coûteuse que la précédente. Sa lance du serment n''est pas seulement une arme d''allonge ; c''est un compas froid, une manière de garder l''adversaire à la distance exacte où il souffre le plus. Le Traqueur ne cherche pas forcément la mort rapide. Il préfère l''épuisement, la pression, le terrain qui se referme. Face à lui, on a d''abord l''impression d''avoir encore le choix. Puis l''on comprend que ces choix étaient déjà prévus.', '{"bA":{"nom":"Branche A — Lance Drainante","style":"Épuisement","descPhys":"La lance entre, ressort. Mais quelque chose reste — une douleur sourde, diffuse, qui court dans les membres. La cible bouge encore, mais chaque geste lui coûte un peu plus qu''avant.","flavor":"Lance Drainante est une blessure qui continue de parler après l''impact. La cible bouge encore, mais chaque geste devient plus lourd, chaque défense moins naturelle. Le Traqueur ne vole pas seulement de l''énergie : il vole la durée du combat.","paliers":[{"niv":2,"nom":"Lance Drainante","cout":"5 EM — 1 action","desc":"Frappe la cible : 4+Niv dégâts. Simultanément : la cible perd 8 EP."},{"niv":5,"nom":"Lance Drainante","cout":"5 EM — 1 action","desc":"8+Niv dégâts. Cible perd 12 EP."},{"niv":7,"nom":"Lance Drainante","cout":"5 EM — 1 action","desc":"12+Niv dégâts. Cible perd 16 EP."},{"niv":10,"nom":"Lance Drainante","cout":"5 EM — 1 action","desc":"16+Niv dégâts. Cible perd 20 EP."}]},"bB":{"nom":"Branche B — Tenue de Ligne","style":"Contrôle","descPhys":"De loin : la lance se tend, précise, contrôlée. Elle atteint sans que le porteur ait bougé d''un pas. De près : la lance s''enfonce avec toute la puissance du Traqueur derrière elle, puis pousse — un mouvement brusque, sec, qui recrée la distance de force.","flavor":"Tenue de Ligne est la grammaire du Traqueur : loin, il atteint ; près, il repousse. Il ne gagne pas parce qu''il bouge davantage, mais parce qu''il impose à l''autre la distance exacte où la lance a raison.","paliers":[{"niv":2,"nom":"Tenue de Ligne","cout":"5 EM — 1 action","desc":"À distance : frappe à portée de lance, 4+Niv. Au corps à corps : frappe puissante 10+Niv + repousse la cible à distance (les deux doivent utiliser une action de déplacement)."},{"niv":5,"nom":"Tenue de Ligne","cout":"5 EM — 1 action","desc":"Distance : 8+Niv. CAC : 16+Niv + repousse."},{"niv":7,"nom":"Tenue de Ligne","cout":"5 EM — 1 action","desc":"Distance : 12+Niv. CAC : 22+Niv + repousse."},{"niv":10,"nom":"Tenue de Ligne","cout":"5 EM — 1 action","desc":"Distance : 16+Niv. CAC : 28+Niv + repousse."}]}}'),
	('flecheur', 'Flécheur', 'Arc du serment', 3, 5, 4, 10, 'Tranchant', 'basic', false, NULL, '🏹', 'distance', true, 'Le Flécheur est le serment de ceux qui savent attendre sans faiblir. Il ne récompense pas seulement la bonne vue ou la main stable ; il récompense la capacité à garder le monde entier immobile dans sa tête jusqu''à ce que la cible devienne évidente. Son arc du serment n''est pas une arme de panique. C''est une ligne tendue entre patience et conséquence. Le Flécheur paraît souvent distant, presque absent du tumulte, mais cette distance est une concentration. Il voit les trajectoires, les erreurs d''appui, les secondes où l''ennemi cesse de protéger son propre avenir. Quand il tire, ce n''est pas pour participer au combat. C''est pour le corriger.', '{"bA":{"nom":"Branche A — Salve Aveugle","style":"AOE","descPhys":"Plusieurs flèches partent en même temps, en arc large. Elles ne cherchent pas une cible précise — elles saturent l''espace. Quiconque se trouve dans la zone reçoit.","flavor":"Salve Aveugle est le moment où le Flécheur renonce à la perfection pour contrôler une zone entière. Ce n''est pas élégant, pas propre, pas toujours confortable pour les alliés. Mais pendant quelques secondes, le terrain cesse d''appartenir à ceux qui s''y trouvent.","paliers":[{"niv":2,"nom":"Salve Aveugle","cout":"6 EM — 1 action","desc":"Zone à distance. Toutes entités dans la zone — ennemies ET alliées — subissent 7+Niv."},{"niv":5,"nom":"Salve Aveugle","cout":"6 EM — 1 action","desc":"9+Niv à toutes entités dans la zone."},{"niv":7,"nom":"Salve Aveugle","cout":"6 EM — 1 action","desc":"12+Niv à toutes entités dans la zone."},{"niv":10,"nom":"Salve Aveugle","cout":"6 EM — 1 action","desc":"15+Niv à toutes entités dans la zone."}]},"bB":{"nom":"Branche B — Flèche de Jugement","style":"Concentration","descPhys":"Le Flécheur s''immobilise. Tout le reste disparaît — le mouvement, le bruit, les alliés. Il ne reste que la cible et la corde tendue à l''extrême. Plus il attend, plus la flèche porte loin et fort. Quand elle part, c''est une sentence.","flavor":"Flèche de Jugement transforme l''attente en poids. Chaque action conservée devient de la tension dans la corde, du silence dans le bras, de la certitude dans le tir. Quand la flèche part enfin, elle porte avec elle tout ce que le Flécheur a refusé de faire avant.","paliers":[{"niv":2,"nom":"Flèche de Jugement","cout":"8 EM — coûte toutes les actions restantes du tour","desc":"0 action sacrifiée : 7+Niv. 1 action : 14+Niv. 2 actions : 20+Niv. Interdit en surcadençage."},{"niv":5,"nom":"Flèche de Jugement","cout":"8 EM","desc":"0 action : 11+Niv. 1 action : 18+Niv. 2 actions : 26+Niv."},{"niv":7,"nom":"Flèche de Jugement","cout":"8 EM","desc":"0 action : 15+Niv. 1 action : 22+Niv. 2 actions : 32+Niv."},{"niv":10,"nom":"Flèche de Jugement","cout":"8 EM","desc":"0 action : 19+Niv. 1 action : 28+Niv. 2 actions : 38+Niv."}]}}'),
	('elementaliste', 'Elementaliste', 'Poing américain du serment serti de gemmes', 4, 4, 4, 7, 'Contondant', 'basic', false, NULL, '👊', 'melee', true, 'L''Élémentaliste est choisi par les âmes capables de porter deux catastrophes contraires sans se déchirer. Ce serment ne donne pas le feu, la glace, la foudre ou l''eau à quelqu''un qui veut seulement faire du bruit. Il répond à ceux qui savent alterner, contenir, relâcher, reprendre. Son poing américain serti de gemmes ressemble moins à une arme qu''à un verrou posé sur des forces trop anciennes pour être aimables. Chaque gemme retient une humeur du monde. Chaque frappe ouvre une serrure différente. L''Élémentaliste paraît souvent calme parce qu''il doit l''être : s''il cesse de tenir l''équilibre, ce ne sont plus ses poings qui parlent, mais les éléments qui commencent à le manger vivant.
